    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`production_order_id`), '') AS BIGINT) AS `production_order_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`storage_location_id`), '') AS BIGINT) AS `storage_location_id`,
    TRY_CAST(NULLIF(trim(`supplier_id`), '') AS BIGINT) AS `supplier_id`,
    TRY_CAST(NULLIF(trim(`supplier_site_id`), '') AS BIGINT) AS `supplier_site_id`,
    TRY_CAST(NULLIF(trim(`asn_line_number`), '') AS INT) AS `asn_line_number`,
    NULLIF(trim(`asn_number`), '') AS `asn_number`,
    CASE lower(trim(`condition_code`))
      WHEN 'good' THEN 'good'
      WHEN 'damaged' THEN 'damaged'
      WHEN 'expired' THEN 'expired'
      WHEN 'quarantine' THEN 'quarantine'
      WHEN 'rejected' THEN 'rejected'
      WHEN 'hold' THEN 'hold'
      ELSE NULLIF(trim(`condition_code`), '')
    END AS `condition_code`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    NULLIF(trim(`damage_description`), '') AS `damage_description`,
    TRY_CAST(NULLIF(trim(`expected_quantity_cases`), '') AS DECIMAL(15,3)) AS `expected_quantity_cases`,
    TRY_CAST(NULLIF(trim(`expected_quantity_eaches`), '') AS DECIMAL(15,3)) AS `expected_quantity_eaches`,
    COALESCE(try_to_date(trim(`expiry_date`), 'yyyy-MM-dd'), try_to_date(trim(`expiry_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`expiry_date`) AS DATE)) AS `expiry_date`,
    TRY_CAST(NULLIF(trim(`extended_cost`), '') AS DECIMAL(18,4)) AS `extended_cost`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    TRY_CAST(NULLIF(trim(`line_number`), '') AS INT) AS `line_number`,
    NULLIF(trim(`lot_number`), '') AS `lot_number`,
    COALESCE(try_to_date(trim(`manufacture_date`), 'yyyy-MM-dd'), try_to_date(trim(`manufacture_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`manufacture_date`) AS DATE)) AS `manufacture_date`,
    NULLIF(trim(`pallet_code`), '') AS `pallet_code`,
    COALESCE(try_to_timestamp(trim(`put_away_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`put_away_timestamp`) AS TIMESTAMP)) AS `put_away_timestamp`,
    CASE WHEN lower(trim(`quality_inspection_required_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`quality_inspection_required_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `quality_inspection_required_flag`,
    CASE lower(trim(`quality_inspection_status`))
      WHEN 'not_required' THEN 'not_required'
      WHEN 'pending' THEN 'pending'
      WHEN 'in_progress' THEN 'in_progress'
      WHEN 'passed' THEN 'passed'
      WHEN 'failed' THEN 'failed'
      WHEN 'conditional' THEN 'conditional'
      ELSE NULLIF(trim(`quality_inspection_status`), '')
    END AS `quality_inspection_status`,
    CASE lower(trim(`receipt_status`))
      WHEN 'pending' THEN 'pending'
      WHEN 'received' THEN 'received'
      WHEN 'inspected' THEN 'inspected'
      WHEN 'put_away' THEN 'put_away'
      WHEN 'discrepancy' THEN 'discrepancy'
      WHEN 'rejected' THEN 'rejected'
      ELSE NULLIF(trim(`receipt_status`), '')
    END AS `receipt_status`,
    TRY_CAST(NULLIF(trim(`received_quantity_cases`), '') AS DECIMAL(15,3)) AS `received_quantity_cases`,
    TRY_CAST(NULLIF(trim(`received_quantity_eaches`), '') AS DECIMAL(15,3)) AS `received_quantity_eaches`,
    COALESCE(try_to_timestamp(trim(`received_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`received_timestamp`) AS TIMESTAMP)) AS `received_timestamp`,
    NULLIF(trim(`sscc`), '') AS `sscc`,
    TRY_CAST(NULLIF(trim(`temperature_at_receipt_celsius`), '') AS DECIMAL(5,2)) AS `temperature_at_receipt_celsius`,
    TRY_CAST(NULLIF(trim(`unit_cost`), '') AS DECIMAL(15,4)) AS `unit_cost`,
    CASE lower(trim(`unit_of_measure`))
      WHEN 'case' THEN 'case'
      WHEN 'each' THEN 'each'
      WHEN 'pallet' THEN 'pallet'
      WHEN 'layer' THEN 'layer'
      WHEN 'inner_pack' THEN 'inner_pack'
      WHEN 'display_unit' THEN 'display_unit'
      ELSE NULLIF(trim(`unit_of_measure`), '')
    END AS `unit_of_measure`,
    NULLIF(trim(`upc`), '') AS `upc`,
    TRY_CAST(NULLIF(trim(`variance_quantity_cases`), '') AS DECIMAL(15,3)) AS `variance_quantity_cases`,
    TRY_CAST(NULLIF(trim(`variance_quantity_eaches`), '') AS DECIMAL(15,3)) AS `variance_quantity_eaches`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.distribution_inbound_receipt_line
)
SELECT *
FROM typed
QUALIFY `inbound_receipt_line_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `inbound_receipt_line_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- distribution.outbound_order ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.distribution_outbound_order (
  CONSTRAINT `outbound_order_id_not_null` EXPECT (`outbound_order_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: distribution.outbound_order typed and cleaned, one row per outbound_order_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`outbound_order_id`), '') AS BIGINT) AS `outbound_order_id`,
    TRY_CAST(NULLIF(trim(`company_code_id`), '') AS BIGINT) AS `company_code_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`demand_plan_id`), '') AS BIGINT) AS `demand_plan_id`,
    TRY_CAST(NULLIF(trim(`event_id`), '') AS BIGINT) AS `event_id`,
    TRY_CAST(NULLIF(trim(`inventory_policy_id`), '') AS BIGINT) AS `inventory_policy_id`,
    TRY_CAST(NULLIF(trim(`network_node_id`), '') AS BIGINT) AS `network_node_id`,
    TRY_CAST(NULLIF(trim(`order_id`), '') AS BIGINT) AS `order_id`,
    TRY_CAST(NULLIF(trim(`primary_outbound_distribution_facility_id`), '') AS BIGINT) AS `primary_outbound_distribution_facility_id`,
    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`production_order_id`), '') AS BIGINT) AS `production_order_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    TRY_CAST(NULLIF(trim(`purchase_order_id`), '') AS BIGINT) AS `purchase_order_id`,
    TRY_CAST(NULLIF(trim(`retail_store_id`), '') AS BIGINT) AS `retail_store_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`source_manufacturing_facility_id`), '') AS BIGINT) AS `source_manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    COALESCE(try_to_date(trim(`actual_delivery_date`), 'yyyy-MM-dd'), try_to_date(trim(`actual_delivery_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`actual_delivery_date`) AS DATE)) AS `actual_delivery_date`,
    COALESCE(try_to_date(trim(`actual_ship_date`), 'yyyy-MM-dd'), try_to_date(trim(`actual_ship_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`actual_ship_date`) AS DATE)) AS `actual_ship_date`,
    CASE WHEN lower(trim(`backorder_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`backorder_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `backorder_flag`,
    NULLIF(trim(`bill_of_lading_number`), '') AS `bill_of_lading_number`,
    NULLIF(trim(`cancellation_reason`), '') AS `cancellation_reason`,
    COALESCE(try_to_timestamp(trim(`cancelled_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`cancelled_timestamp`) AS TIMESTAMP)) AS `cancelled_timestamp`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    TRY_CAST(NULLIF(trim(`fill_rate_percentage`), '') AS DECIMAL(5,2)) AS `fill_rate_percentage`,
    CASE WHEN lower(trim(`hazmat_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`hazmat_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `hazmat_flag`,
    NULLIF(trim(`incoterm`), '') AS `incoterm`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    COALESCE(try_to_date(trim(`order_date`), 'yyyy-MM-dd'), try_to_date(trim(`order_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`order_date`) AS DATE)) AS `order_date`,
    NULLIF(trim(`order_status`), '') AS `order_status`,
    CASE lower(trim(`order_type`))
      WHEN 'retail_replenishment' THEN 'retail_replenishment'
      WHEN 'dsd' THEN 'dsd'
      WHEN 'ecommerce' THEN 'ecommerce'
      WHEN 'inter_dc_transfer' THEN 'inter_dc_transfer'
      WHEN 'wholesale' THEN 'wholesale'
      WHEN 'export' THEN 'export'
      ELSE NULLIF(trim(`order_type`), '')
    END AS `order_type`,
    CASE WHEN lower(trim(`otif_commitment_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`otif_commitment_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `otif_commitment_flag`,
    NULLIF(trim(`packing_slip_number`), '') AS `packing_slip_number`,
    NULLIF(trim(`payment_terms`), '') AS `payment_terms`,
    NULLIF(trim(`pick_ticket_number`), '') AS `pick_ticket_number`,
    CASE lower(trim(`priority_code`))
      WHEN 'standard' THEN 'standard'
      WHEN 'expedited' THEN 'expedited'
      WHEN 'rush' THEN 'rush'
      WHEN 'critical' THEN 'critical'
      ELSE NULLIF(trim(`priority_code`), '')
    END AS `priority_code`,
    COALESCE(try_to_timestamp(trim(`proof_of_delivery_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`proof_of_delivery_timestamp`) AS TIMESTAMP)) AS `proof_of_delivery_timestamp`,
    COALESCE(try_to_date(trim(`requested_ship_date`), 'yyyy-MM-dd'), try_to_date(trim(`requested_ship_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`requested_ship_date`) AS DATE)) AS `requested_ship_date`,
    COALESCE(try_to_date(trim(`required_delivery_date`), 'yyyy-MM-dd'), try_to_date(trim(`required_delivery_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`required_delivery_date`) AS DATE)) AS `required_delivery_date`,
    CASE lower(trim(`service_level`))
      WHEN 'standard' THEN 'standard'
      WHEN 'next_day' THEN 'next_day'
      WHEN 'two_day' THEN 'two_day'
      WHEN 'same_day' THEN 'same_day'
      WHEN 'scheduled' THEN 'scheduled'
      ELSE NULLIF(trim(`service_level`), '')
    END AS `service_level`,
    NULLIF(trim(`shipping_method`), '') AS `shipping_method`,
    NULLIF(trim(`special_handling_instructions`), '') AS `special_handling_instructions`,
    CASE WHEN lower(trim(`temperature_controlled_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`temperature_controlled_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `temperature_controlled_flag`,
    TRY_CAST(NULLIF(trim(`total_order_quantity`), '') AS DECIMAL(15,3)) AS `total_order_quantity`,
    TRY_CAST(NULLIF(trim(`total_order_value`), '') AS DECIMAL(15,2)) AS `total_order_value`,
    TRY_CAST(NULLIF(trim(`total_order_volume_m3`), '') AS DECIMAL(12,3)) AS `total_order_volume_m3`,
    TRY_CAST(NULLIF(trim(`total_order_weight_kg`), '') AS DECIMAL(12,3)) AS `total_order_weight_kg`,
    NULLIF(trim(`tracking_number`), '') AS `tracking_number`,
    TRY_CAST(NULLIF(trim(`wave_code`), '') AS BIGINT) AS `wave_code`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.distribution_outbound_order
)
SELECT *
FROM typed
QUALIFY `outbound_order_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `outbound_order_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- distribution.outbound_order_line ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.distribution_outbound_order_line (
  CONSTRAINT `outbound_order_line_id_not_null` EXPECT (`outbound_order_line_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: distribution.outbound_order_line typed and cleaned, one row per outbound_order_line_id (latest _ingested_at wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`outbound_order_line_id`), '') AS BIGINT) AS `outbound_order_line_id`,
    TRY_CAST(NULLIF(trim(`batch_record_id`), '') AS BIGINT) AS `batch_record_id`,
    TRY_CAST(NULLIF(trim(`event_id`), '') AS BIGINT) AS `event_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`gtin_registry_id`), '') AS BIGINT) AS `gtin_registry_id`,
    TRY_CAST(NULLIF(trim(`outbound_order_id`), '') AS BIGINT) AS `outbound_order_id`,
    TRY_CAST(NULLIF(trim(`production_order_id`), '') AS BIGINT) AS `production_order_id`,
    TRY_CAST(NULLIF(trim(`promoted_price_id`), '') AS BIGINT) AS `promoted_price_id`,
    TRY_CAST(NULLIF(trim(`shipment_id`), '') AS BIGINT) AS `shipment_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`storage_location_id`), '') AS BIGINT) AS `storage_location_id`,
    COALESCE(try_to_date(trim(`actual_ship_date`), 'yyyy-MM-dd'), try_to_date(trim(`actual_ship_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`actual_ship_date`) AS DATE)) AS `actual_ship_date`,
    TRY_CAST(NULLIF(trim(`allocated_quantity`), '') AS DECIMAL(15,3)) AS `allocated_quantity`,
    TRY_CAST(NULLIF(trim(`base_unit_quantity`), '') AS DECIMAL(15,3)) AS `base_unit_quantity`,
    TRY_CAST(NULLIF(trim(`confirmed_quantity`), '') AS DECIMAL(15,3)) AS `confirmed_quantity`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`customer_po_line_number`), '') AS `customer_po_line_number`,
    CASE WHEN lower(trim(`dsd_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`dsd_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `dsd_flag`,
    NULLIF(trim(`edi_line_reference`), '') AS `edi_line_reference`,
    COALESCE(try_to_date(trim(`expiry_date`), 'yyyy-MM-dd'), try_to_date(trim(`expiry_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`expiry_date`) AS DATE)) AS `expiry_date`,
    NULLIF(trim(`handling_unit_code`), '') AS `handling_unit_code`,
    CASE WHEN lower(trim(`hazmat_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`hazmat_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `hazmat_flag`,
    TRY_CAST(NULLIF(trim(`line_number`), '') AS INT) AS `line_number`,
    NULLIF(trim(`line_status`), '') AS `line_status`,
    TRY_CAST(NULLIF(trim(`line_volume_m3`), '') AS DECIMAL(15,6)) AS `line_volume_m3`,
    TRY_CAST(NULLIF(trim(`line_weight_kg`), '') AS DECIMAL(15,3)) AS `line_weight_kg`,
    NULLIF(trim(`lot_number`), '') AS `lot_number`,
    TRY_CAST(NULLIF(trim(`ordered_quantity`), '') AS DECIMAL(15,3)) AS `ordered_quantity`,
    CASE lower(trim(`otif_status`))
      WHEN 'on_time_in_full' THEN 'on_time_in_full'
      WHEN 'late_in_full' THEN 'late_in_full'
      WHEN 'on_time_partial' THEN 'on_time_partial'
      WHEN 'late_partial' THEN 'late_partial'
      ELSE NULLIF(trim(`otif_status`), '')
    END AS `otif_status`,
    COALESCE(try_to_timestamp(trim(`pack_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`pack_timestamp`) AS TIMESTAMP)) AS `pack_timestamp`,
    TRY_CAST(NULLIF(trim(`packed_quantity`), '') AS DECIMAL(15,3)) AS `packed_quantity`,
    NULLIF(trim(`pallet_code`), '') AS `pallet_code`,
    COALESCE(try_to_timestamp(trim(`pick_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`pick_timestamp`) AS TIMESTAMP)) AS `pick_timestamp`,
    NULLIF(trim(`pick_zone`), '') AS `pick_zone`,
    TRY_CAST(NULLIF(trim(`picked_quantity`), '') AS DECIMAL(15,3)) AS `picked_quantity`,
    COALESCE(try_to_date(trim(`requested_ship_date`), 'yyyy-MM-dd'), try_to_date(trim(`requested_ship_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`requested_ship_date`) AS DATE)) AS `requested_ship_date`,
    NULLIF(trim(`serial_numbers`), '') AS `serial_numbers`,
    COALESCE(try_to_timestamp(trim(`ship_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`ship_timestamp`) AS TIMESTAMP)) AS `ship_timestamp`,
    TRY_CAST(NULLIF(trim(`shipped_quantity`), '') AS DECIMAL(15,3)) AS `shipped_quantity`,
    CASE WHEN lower(trim(`short_ship_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`short_ship_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `short_ship_flag`,
    CASE lower(trim(`short_ship_reason_code`))
      WHEN 'oos' THEN 'OOS'
      WHEN 'damage' THEN 'DAMAGE'
      WHEN 'recall' THEN 'RECALL'
      WHEN 'expired' THEN 'EXPIRED'
      WHEN 'allocation' THEN 'ALLOCATION'
      ELSE NULLIF(trim(`short_ship_reason_code`), '')
    END AS `short_ship_reason_code`,
    CASE WHEN lower(trim(`temperature_controlled_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`temperature_controlled_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `temperature_controlled_flag`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    TRY_CAST(NULLIF(trim(`unit_volume_m3`), '') AS DECIMAL(12,6)) AS `unit_volume_m3`,
    TRY_CAST(NULLIF(trim(`unit_weight_kg`), '') AS DECIMAL(12,3)) AS `unit_weight_kg`,
    NULLIF(trim(`upc`), '') AS `upc`,
    NULLIF(trim(`warehouse_location_code`), '') AS `warehouse_location_code`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.distribution_outbound_order_line
)
SELECT *
FROM typed
QUALIFY `outbound_order_line_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `outbound_order_line_id` ORDER BY _ingested_at DESC) = 1;

-- distribution.pick_task ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.distribution_pick_task (
  CONSTRAINT `pick_task_id_not_null` EXPECT (`pick_task_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: distribution.pick_task typed and cleaned, one row per pick_task_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`pick_task_id`), '') AS BIGINT) AS `pick_task_id`,
    TRY_CAST(NULLIF(trim(`atp_record_id`), '') AS BIGINT) AS `atp_record_id`,
    TRY_CAST(NULLIF(trim(`batch_record_id`), '') AS BIGINT) AS `batch_record_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`destination_location_distribution_storage_location_id`), '') AS BIGINT) AS `destination_location_distribution_storage_location_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`outbound_order_id`), '') AS BIGINT) AS `outbound_order_id`,
    TRY_CAST(NULLIF(trim(`outbound_order_line_id`), '') AS BIGINT) AS `outbound_order_line_id`,
    TRY_CAST(NULLIF(trim(`primary_pick_distribution_storage_location_id`), '') AS BIGINT) AS `primary_pick_distribution_storage_location_id`,
    TRY_CAST(NULLIF(trim(`shipment_id`), '') AS BIGINT) AS `shipment_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    NULLIF(trim(`carton_code`), '') AS `carton_code`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    CASE WHEN lower(trim(`dsd_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`dsd_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `dsd_flag`,
    NULLIF(trim(`exception_code`), '') AS `exception_code`,
    NULLIF(trim(`exception_notes`), '') AS `exception_notes`,
    TRY_CAST(NULLIF(trim(`gross_weight_kg`), '') AS DECIMAL(12,3)) AS `gross_weight_kg`,
    NULLIF(trim(`gs1_128_label`), '') AS `gs1_128_label`,
    TRY_CAST(NULLIF(trim(`height_cm`), '') AS DECIMAL(10,2)) AS `height_cm`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    TRY_CAST(NULLIF(trim(`length_cm`), '') AS DECIMAL(10,2)) AS `length_cm`,
    TRY_CAST(NULLIF(trim(`net_weight_kg`), '') AS DECIMAL(12,3)) AS `net_weight_kg`,
    CASE WHEN lower(trim(`otif_eligible_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`otif_eligible_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `otif_eligible_flag`,
    TRY_CAST(NULLIF(trim(`pack_station_code`), '') AS BIGINT) AS `pack_station_code`,
    NULLIF(trim(`packaging_material_code`), '') AS `packaging_material_code`,
    NULLIF(trim(`pallet_code`), '') AS `pallet_code`,
    CASE WHEN lower(trim(`pick_accuracy_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`pick_accuracy_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `pick_accuracy_flag`,
    NULLIF(trim(`pick_list_number`), '') AS `pick_list_number`,
    TRY_CAST(NULLIF(trim(`pick_quantity`), '') AS DECIMAL(15,3)) AS `pick_quantity`,
    TRY_CAST(NULLIF(trim(`picked_quantity`), '') AS DECIMAL(15,3)) AS `picked_quantity`,
    CASE lower(trim(`picking_strategy`))
      WHEN 'discrete' THEN 'discrete'
      WHEN 'batch' THEN 'batch'
      WHEN 'zone' THEN 'zone'
      WHEN 'wave' THEN 'wave'
      WHEN 'cluster' THEN 'cluster'
      ELSE NULLIF(trim(`picking_strategy`), '')
    END AS `picking_strategy`,
    CASE lower(trim(`priority_level`))
      WHEN 'urgent' THEN 'urgent'
      WHEN 'high' THEN 'high'
      WHEN 'normal' THEN 'normal'
      WHEN 'low' THEN 'low'
      ELSE NULLIF(trim(`priority_level`), '')
    END AS `priority_level`,
    NULLIF(trim(`sscc`), '') AS `sscc`,
    COALESCE(try_to_timestamp(trim(`task_assigned_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`task_assigned_timestamp`) AS TIMESTAMP)) AS `task_assigned_timestamp`,
    COALESCE(try_to_timestamp(trim(`task_completed_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`task_completed_timestamp`) AS TIMESTAMP)) AS `task_completed_timestamp`,
    TRY_CAST(NULLIF(trim(`task_duration_seconds`), '') AS INT) AS `task_duration_seconds`,
    COALESCE(try_to_timestamp(trim(`task_started_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`task_started_timestamp`) AS TIMESTAMP)) AS `task_started_timestamp`,
    CASE lower(trim(`task_status`))
      WHEN 'pending' THEN 'pending'
      WHEN 'assigned' THEN 'assigned'
      WHEN 'in_progress' THEN 'in_progress'
      WHEN 'completed' THEN 'completed'
      WHEN 'cancelled' THEN 'cancelled'
      WHEN 'on_hold' THEN 'on_hold'
      ELSE NULLIF(trim(`task_status`), '')
    END AS `task_status`,
    CASE lower(trim(`task_type`))
      WHEN 'pick' THEN 'pick'
      WHEN 'pack' THEN 'pack'
      WHEN 'pick_and_pack' THEN 'pick_and_pack'
      WHEN 'replenishment_pick' THEN 'replenishment_pick'
      ELSE NULLIF(trim(`task_type`), '')
    END AS `task_type`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    TRY_CAST(NULLIF(trim(`wave_code`), '') AS BIGINT) AS `wave_code`,
    TRY_CAST(NULLIF(trim(`width_cm`), '') AS DECIMAL(10,2)) AS `width_cm`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.distribution_pick_task
)
SELECT *
FROM typed
QUALIFY `pick_task_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `pick_task_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- distribution.shipment ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.distribution_shipment (
  CONSTRAINT `shipment_id_not_null` EXPECT (`shipment_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: distribution.shipment typed and cleaned, one row per shipment_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`shipment_id`), '') AS BIGINT) AS `shipment_id`,
    TRY_CAST(NULLIF(trim(`company_code_id`), '') AS BIGINT) AS `company_code_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`event_id`), '') AS BIGINT) AS `event_id`,
    TRY_CAST(NULLIF(trim(`gl_account_id`), '') AS BIGINT) AS `gl_account_id`,
    TRY_CAST(NULLIF(trim(`load_plan_id`), '') AS BIGINT) AS `load_plan_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`network_node_id`), '') AS BIGINT) AS `network_node_id`,
    TRY_CAST(NULLIF(trim(`order_id`), '') AS BIGINT) AS `order_id`,
    TRY_CAST(NULLIF(trim(`outbound_order_id`), '') AS BIGINT) AS `outbound_order_id`,
    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    TRY_CAST(NULLIF(trim(`retail_store_id`), '') AS BIGINT) AS `retail_store_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`source_distribution_facility_id`), '') AS BIGINT) AS `source_distribution_facility_id`,
    TRY_CAST(NULLIF(trim(`trade_account_id`), '') AS BIGINT) AS `trade_account_id`,
    COALESCE(try_to_timestamp(trim(`actual_delivery_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`actual_delivery_timestamp`) AS TIMESTAMP)) AS `actual_delivery_timestamp`,
    COALESCE(try_to_timestamp(trim(`actual_departure_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`actual_departure_timestamp`) AS TIMESTAMP)) AS `actual_departure_timestamp`,
    NULLIF(trim(`bill_of_lading_number`), '') AS `bill_of_lading_number`,
    NULLIF(trim(`carrier_code`), '') AS `carrier_code`,
    NULLIF(trim(`carrier_name`), '') AS `carrier_name`,
    CASE lower(trim(`carrier_service_level`))
      WHEN 'ground' THEN 'ground'
      WHEN 'express' THEN 'express'
      WHEN 'overnight' THEN 'overnight'
      WHEN 'two_day' THEN 'two_day'
      WHEN 'economy' THEN 'economy'
      WHEN 'premium' THEN 'premium'
      ELSE NULLIF(trim(`carrier_service_level`), '')
    END AS `carrier_service_level`,
    TRY_CAST(NULLIF(trim(`carton_count`), '') AS INT) AS `carton_count`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`destination_address_line1`), '') AS `destination_address_line1`,
    NULLIF(trim(`destination_city`), '') AS `destination_city`,
    NULLIF(trim(`destination_code`), '') AS `destination_code`,
    NULLIF(trim(`destination_country_code`), '') AS `destination_country_code`,
    NULLIF(trim(`destination_name`), '') AS `destination_name`,
    NULLIF(trim(`destination_postal_code`), '') AS `destination_postal_code`,
    NULLIF(trim(`destination_state_province`), '') AS `destination_state_province`,
    CASE lower(trim(`destination_type`))
      WHEN 'retail_store' THEN 'retail_store'
      WHEN 'distribution_center' THEN 'distribution_center'
      WHEN 'customer' THEN 'customer'
      WHEN 'warehouse' THEN 'warehouse'
      WHEN 'third_party' THEN 'third_party'
      ELSE NULLIF(trim(`destination_type`), '')
    END AS `destination_type`,
    NULLIF(trim(`dock_door_number`), '') AS `dock_door_number`,
    COALESCE(try_to_timestamp(trim(`estimated_delivery_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`estimated_delivery_timestamp`) AS TIMESTAMP)) AS `estimated_delivery_timestamp`,
    TRY_CAST(NULLIF(trim(`freight_charge_amount`), '') AS DECIMAL(15,2)) AS `freight_charge_amount`,
    NULLIF(trim(`freight_currency_code`), '') AS `freight_currency_code`,
    CASE lower(trim(`freight_terms`))
      WHEN 'prepaid' THEN 'prepaid'
      WHEN 'collect' THEN 'collect'
      WHEN 'third_party' THEN 'third_party'
      WHEN 'fob_origin' THEN 'fob_origin'
      WHEN 'fob_destination' THEN 'fob_destination'
      ELSE NULLIF(trim(`freight_terms`), '')
    END AS `freight_terms`,
    NULLIF(trim(`goods_issue_document_number`), '') AS `goods_issue_document_number`,
    CASE WHEN lower(trim(`hazmat_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`hazmat_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `hazmat_flag`,
    CASE WHEN lower(trim(`in_full_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`in_full_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `in_full_flag`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    TRY_CAST(NULLIF(trim(`line_item_count`), '') AS INT) AS `line_item_count`,
    CASE WHEN lower(trim(`on_time_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`on_time_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `on_time_flag`,
    CASE lower(trim(`otif_status`))
      WHEN 'on_time_in_full' THEN 'on_time_in_full'
      WHEN 'late' THEN 'late'
      WHEN 'incomplete' THEN 'incomplete'
      WHEN 'damaged' THEN 'damaged'
      WHEN 'not_applicable' THEN 'not_applicable'
      ELSE NULLIF(trim(`otif_status`), '')
    END AS `otif_status`,
    TRY_CAST(NULLIF(trim(`pallet_count`), '') AS INT) AS `pallet_count`,
    NULLIF(trim(`pro_number`), '') AS `pro_number`,
    COALESCE(try_to_date(trim(`scheduled_delivery_date`), 'yyyy-MM-dd'), try_to_date(trim(`scheduled_delivery_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`scheduled_delivery_date`) AS DATE)) AS `scheduled_delivery_date`,
    COALESCE(try_to_timestamp(trim(`scheduled_delivery_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`scheduled_delivery_timestamp`) AS TIMESTAMP)) AS `scheduled_delivery_timestamp`,
    COALESCE(try_to_timestamp(trim(`scheduled_departure_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`scheduled_departure_timestamp`) AS TIMESTAMP)) AS `scheduled_departure_timestamp`,
    COALESCE(try_to_date(trim(`scheduled_ship_date`), 'yyyy-MM-dd'), try_to_date(trim(`scheduled_ship_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`scheduled_ship_date`) AS DATE)) AS `scheduled_ship_date`,
    NULLIF(trim(`seal_number`), '') AS `seal_number`,
    NULLIF(trim(`shipment_number`), '') AS `shipment_number`,
    NULLIF(trim(`shipment_status`), '') AS `shipment_status`,
    CASE lower(trim(`shipment_type`))
      WHEN 'standard' THEN 'standard'
      WHEN 'expedited' THEN 'expedited'
      WHEN 'dsd' THEN 'dsd'
      WHEN 'cross_dock' THEN 'cross_dock'
      WHEN 'transfer' THEN 'transfer'
      WHEN 'return' THEN 'return'
      ELSE NULLIF(trim(`shipment_type`), '')
    END AS `shipment_type`,
    CASE WHEN lower(trim(`temperature_controlled_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`temperature_controlled_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `temperature_controlled_flag`,
    TRY_CAST(NULLIF(trim(`total_units`), '') AS INT) AS `total_units`,
    TRY_CAST(NULLIF(trim(`total_volume_cubic_meters`), '') AS DECIMAL(12,3)) AS `total_volume_cubic_meters`,
    TRY_CAST(NULLIF(trim(`total_weight_kg`), '') AS DECIMAL(12,3)) AS `total_weight_kg`,
    NULLIF(trim(`tracking_number`), '') AS `tracking_number`,
    NULLIF(trim(`trailer_number`), '') AS `trailer_number`,
    NULLIF(trim(`wave_number`), '') AS `wave_number`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.distribution_shipment
)
SELECT *
FROM typed
QUALIFY `shipment_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `shipment_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- distribution.inventory_position ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.distribution_inventory_position (
  CONSTRAINT `inventory_position_id_not_null` EXPECT (`inventory_position_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: distribution.inventory_position typed and cleaned, one row per inventory_position_id (latest last_updated_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`inventory_position_id`), '') AS BIGINT) AS `inventory_position_id`,
    TRY_CAST(NULLIF(trim(`batch_record_id`), '') AS BIGINT) AS `batch_record_id`,
    TRY_CAST(NULLIF(trim(`company_code_id`), '') AS BIGINT) AS `company_code_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`event_id`), '') AS BIGINT) AS `event_id`,
    TRY_CAST(NULLIF(trim(`inventory_policy_id`), '') AS BIGINT) AS `inventory_policy_id`,
    TRY_CAST(NULLIF(trim(`manufacturing_facility_id`), '') AS BIGINT) AS `manufacturing_facility_id`,
    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`profit_center_id`), '') AS BIGINT) AS `profit_center_id`,
    TRY_CAST(NULLIF(trim(`safety_stock_id`), '') AS BIGINT) AS `safety_stock_id`,
    TRY_CAST(NULLIF(trim(`sku_id`), '') AS BIGINT) AS `sku_id`,
    TRY_CAST(NULLIF(trim(`standard_cost_id`), '') AS BIGINT) AS `standard_cost_id`,
    TRY_CAST(NULLIF(trim(`storage_location_id`), '') AS BIGINT) AS `storage_location_id`,
    TRY_CAST(NULLIF(trim(`actual_weight`), '') AS DECIMAL(18,3)) AS `actual_weight`,
    CASE WHEN lower(trim(`catch_weight_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`catch_weight_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `catch_weight_flag`,
    TRY_CAST(NULLIF(trim(`cost_per_unit`), '') AS DECIMAL(18,4)) AS `cost_per_unit`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`currency_code`), '') AS `currency_code`,
    TRY_CAST(NULLIF(trim(`days_on_hand`), '') AS INT) AS `days_on_hand`,
    TRY_CAST(NULLIF(trim(`days_to_expiry`), '') AS INT) AS `days_to_expiry`,
    COALESCE(try_to_date(trim(`expiry_date`), 'yyyy-MM-dd'), try_to_date(trim(`expiry_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`expiry_date`) AS DATE)) AS `expiry_date`,
    CASE lower(trim(`inventory_condition`))
      WHEN 'new' THEN 'new'
      WHEN 'refurbished' THEN 'refurbished'
      WHEN 'returned' THEN 'returned'
      WHEN 'damaged' THEN 'damaged'
      WHEN 'expired' THEN 'expired'
      WHEN 'recalled' THEN 'recalled'
      ELSE NULLIF(trim(`inventory_condition`), '')
    END AS `inventory_condition`,
    CASE lower(trim(`inventory_status`))
      WHEN 'available' THEN 'available'
      WHEN 'allocated' THEN 'allocated'
      WHEN 'quarantine' THEN 'quarantine'
      WHEN 'hold' THEN 'hold'
      WHEN 'damaged' THEN 'damaged'
      WHEN 'expired' THEN 'expired'
      ELSE NULLIF(trim(`inventory_status`), '')
    END AS `inventory_status`,
    COALESCE(try_to_date(trim(`last_cycle_count_date`), 'yyyy-MM-dd'), try_to_date(trim(`last_cycle_count_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`last_cycle_count_date`) AS DATE)) AS `last_cycle_count_date`,
    COALESCE(try_to_date(trim(`last_movement_date`), 'yyyy-MM-dd'), try_to_date(trim(`last_movement_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`last_movement_date`) AS DATE)) AS `last_movement_date`,
    NULLIF(trim(`last_movement_type`), '') AS `last_movement_type`,
    COALESCE(try_to_timestamp(trim(`last_updated_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_updated_timestamp`) AS TIMESTAMP)) AS `last_updated_timestamp`,
    NULLIF(trim(`license_plate_number`), '') AS `license_plate_number`,
    NULLIF(trim(`lot_number`), '') AS `lot_number`,
    COALESCE(try_to_date(trim(`manufacture_date`), 'yyyy-MM-dd'), try_to_date(trim(`manufacture_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`manufacture_date`) AS DATE)) AS `manufacture_date`,
    CASE lower(trim(`owner_type`))
      WHEN 'owned' THEN 'owned'
      WHEN 'consignment' THEN 'consignment'
      WHEN 'customer_owned' THEN 'customer_owned'
      WHEN 'vendor_managed' THEN 'vendor_managed'
      ELSE NULLIF(trim(`owner_type`), '')
    END AS `owner_type`,
    NULLIF(trim(`pallet_code`), '') AS `pallet_code`,
    CASE WHEN lower(trim(`pick_face_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`pick_face_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `pick_face_flag`,
    COALESCE(try_to_date(trim(`putaway_date`), 'yyyy-MM-dd'), try_to_date(trim(`putaway_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`putaway_date`) AS DATE)) AS `putaway_date`,
    TRY_CAST(NULLIF(trim(`quantity_allocated`), '') AS DECIMAL(18,3)) AS `quantity_allocated`,
    TRY_CAST(NULLIF(trim(`quantity_available`), '') AS DECIMAL(18,3)) AS `quantity_available`,
    TRY_CAST(NULLIF(trim(`quantity_damaged`), '') AS DECIMAL(18,3)) AS `quantity_damaged`,
    TRY_CAST(NULLIF(trim(`quantity_hold`), '') AS DECIMAL(18,3)) AS `quantity_hold`,
    TRY_CAST(NULLIF(trim(`quantity_on_hand`), '') AS DECIMAL(18,3)) AS `quantity_on_hand`,
    TRY_CAST(NULLIF(trim(`quantity_quarantine`), '') AS DECIMAL(18,3)) AS `quantity_quarantine`,
    TRY_CAST(NULLIF(trim(`quantity_reserved`), '') AS DECIMAL(18,3)) AS `quantity_reserved`,
    COALESCE(try_to_date(trim(`receipt_date`), 'yyyy-MM-dd'), try_to_date(trim(`receipt_date`), 'dd/MM/yyyy'), TRY_CAST(trim(`receipt_date`) AS DATE)) AS `receipt_date`,
    CASE WHEN lower(trim(`replenishment_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`replenishment_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `replenishment_flag`,
    COALESCE(try_to_timestamp(trim(`snapshot_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`snapshot_timestamp`) AS TIMESTAMP)) AS `snapshot_timestamp`,
    NULLIF(trim(`storage_zone`), '') AS `storage_zone`,
    CASE lower(trim(`temperature_zone`))
      WHEN 'ambient' THEN 'ambient'
      WHEN 'refrigerated' THEN 'refrigerated'
      WHEN 'frozen' THEN 'frozen'
      WHEN 'controlled' THEN 'controlled'
      ELSE NULLIF(trim(`temperature_zone`), '')
    END AS `temperature_zone`,
    TRY_CAST(NULLIF(trim(`total_inventory_value`), '') AS DECIMAL(18,2)) AS `total_inventory_value`,
    NULLIF(trim(`unit_of_measure`), '') AS `unit_of_measure`,
    CASE lower(trim(`weight_unit_of_measure`))
      WHEN 'lb' THEN 'LB'
      WHEN 'kg' THEN 'KG'
      WHEN 'oz' THEN 'OZ'
      WHEN 'g' THEN 'G'
      ELSE NULLIF(trim(`weight_unit_of_measure`), '')
    END AS `weight_unit_of_measure`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.distribution_inventory_position
)
SELECT *
FROM typed
QUALIFY `inventory_position_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `inventory_position_id` ORDER BY `last_updated_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;

-- distribution.load_plan ----------------------------------------------------------------
CREATE OR REFRESH MATERIALIZED VIEW ${catalog}.silver.distribution_load_plan (
  CONSTRAINT `load_plan_id_not_null` EXPECT (`load_plan_id` IS NOT NULL) ON VIOLATION DROP ROW
)
COMMENT 'Silver: distribution.load_plan typed and cleaned, one row per load_plan_id (latest last_modified_timestamp wins).'
AS
WITH typed AS (
  SELECT
    TRY_CAST(NULLIF(trim(`load_plan_id`), '') AS BIGINT) AS `load_plan_id`,
    TRY_CAST(NULLIF(trim(`cost_center_id`), '') AS BIGINT) AS `cost_center_id`,
    TRY_CAST(NULLIF(trim(`distribution_facility_id`), '') AS BIGINT) AS `distribution_facility_id`,
    TRY_CAST(NULLIF(trim(`outbound_order_id`), '') AS BIGINT) AS `outbound_order_id`,
    TRY_CAST(NULLIF(trim(`product_category_id`), '') AS BIGINT) AS `product_category_id`,
    TRY_CAST(NULLIF(trim(`retail_store_id`), '') AS BIGINT) AS `retail_store_id`,
    COALESCE(try_to_timestamp(trim(`actual_departure_datetime`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`actual_departure_datetime`) AS TIMESTAMP)) AS `actual_departure_datetime`,
    CASE lower(trim(`carrier_service_level`))
      WHEN 'standard' THEN 'standard'
      WHEN 'expedited' THEN 'expedited'
      WHEN 'next_day' THEN 'next_day'
      WHEN 'two_day' THEN 'two_day'
      WHEN 'economy' THEN 'economy'
      WHEN 'white_glove' THEN 'white_glove'
      ELSE NULLIF(trim(`carrier_service_level`), '')
    END AS `carrier_service_level`,
    TRY_CAST(NULLIF(trim(`case_count`), '') AS INT) AS `case_count`,
    COALESCE(try_to_timestamp(trim(`created_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`created_timestamp`) AS TIMESTAMP)) AS `created_timestamp`,
    NULLIF(trim(`dock_door_number`), '') AS `dock_door_number`,
    CASE WHEN lower(trim(`dsd_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`dsd_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `dsd_flag`,
    TRY_CAST(NULLIF(trim(`estimated_freight_cost`), '') AS DECIMAL(12,2)) AS `estimated_freight_cost`,
    NULLIF(trim(`exception_code`), '') AS `exception_code`,
    NULLIF(trim(`exception_notes`), '') AS `exception_notes`,
    NULLIF(trim(`freight_cost_currency_code`), '') AS `freight_cost_currency_code`,
    NULLIF(trim(`hazmat_class`), '') AS `hazmat_class`,
    CASE WHEN lower(trim(`hazmat_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`hazmat_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `hazmat_flag`,
    COALESCE(try_to_timestamp(trim(`last_modified_timestamp`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`last_modified_timestamp`) AS TIMESTAMP)) AS `last_modified_timestamp`,
    NULLIF(trim(`load_plan_number`), '') AS `load_plan_number`,
    NULLIF(trim(`load_plan_status`), '') AS `load_plan_status`,
    CASE lower(trim(`load_sequence_strategy`))
      WHEN 'fifo' THEN 'fifo'
      WHEN 'lifo' THEN 'lifo'
      WHEN 'stop_sequence' THEN 'stop_sequence'
      WHEN 'priority' THEN 'priority'
      ELSE NULLIF(trim(`load_sequence_strategy`), '')
    END AS `load_sequence_strategy`,
    CASE lower(trim(`load_type`))
      WHEN 'full_truckload' THEN 'full_truckload'
      WHEN 'less_than_truckload' THEN 'less_than_truckload'
      WHEN 'parcel' THEN 'parcel'
      WHEN 'intermodal' THEN 'intermodal'
      WHEN 'dsd' THEN 'dsd'
      WHEN 'pool_distribution' THEN 'pool_distribution'
      ELSE NULLIF(trim(`load_type`), '')
    END AS `load_type`,
    COALESCE(try_to_timestamp(trim(`loading_completion_datetime`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`loading_completion_datetime`) AS TIMESTAMP)) AS `loading_completion_datetime`,
    COALESCE(try_to_timestamp(trim(`loading_start_datetime`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`loading_start_datetime`) AS TIMESTAMP)) AS `loading_start_datetime`,
    TRY_CAST(NULLIF(trim(`order_count`), '') AS INT) AS `order_count`,
    COALESCE(try_to_timestamp(trim(`otif_target_delivery_datetime`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`otif_target_delivery_datetime`) AS TIMESTAMP)) AS `otif_target_delivery_datetime`,
    NULLIF(trim(`pallet_configuration`), '') AS `pallet_configuration`,
    TRY_CAST(NULLIF(trim(`pallet_count`), '') AS INT) AS `pallet_count`,
    COALESCE(try_to_timestamp(trim(`planned_departure_datetime`), 'yyyy-MM-dd HH:mm:ss'), TRY_CAST(trim(`planned_departure_datetime`) AS TIMESTAMP)) AS `planned_departure_datetime`,
    NULLIF(trim(`seal_number`), '') AS `seal_number`,
    TRY_CAST(NULLIF(trim(`stop_count`), '') AS INT) AS `stop_count`,
    CASE WHEN lower(trim(`temperature_controlled_flag`)) IN ('true', 't', 'yes', 'y', '1') THEN TRUE
         WHEN lower(trim(`temperature_controlled_flag`)) IN ('false', 'f', 'no', 'n', '0') THEN FALSE END AS `temperature_controlled_flag`,
    TRY_CAST(NULLIF(trim(`temperature_range_max_celsius`), '') AS DECIMAL(5,2)) AS `temperature_range_max_celsius`,
    TRY_CAST(NULLIF(trim(`temperature_range_min_celsius`), '') AS DECIMAL(5,2)) AS `temperature_range_min_celsius`,
    TRY_CAST(NULLIF(trim(`total_volume_cubic_meters`), '') AS DECIMAL(12,3)) AS `total_volume_cubic_meters`,
    TRY_CAST(NULLIF(trim(`total_weight_kg`), '') AS DECIMAL(12,2)) AS `total_weight_kg`,
    NULLIF(trim(`trailer_code`), '') AS `trailer_code`,
    CASE lower(trim(`trailer_type`))
      WHEN 'dry_van' THEN 'dry_van'
      WHEN 'refrigerated' THEN 'refrigerated'
      WHEN 'flatbed' THEN 'flatbed'
      WHEN 'tanker' THEN 'tanker'
      WHEN 'intermodal' THEN 'intermodal'
      WHEN 'box_truck' THEN 'box_truck'
      ELSE NULLIF(trim(`trailer_type`), '')
    END AS `trailer_type`,
    TRY_CAST(NULLIF(trim(`trailer_utilization_percentage`), '') AS DECIMAL(5,2)) AS `trailer_utilization_percentage`,
    _source_file,
    _ingested_at
  FROM ${catalog}.bronze.distribution_load_plan
)
SELECT *
FROM typed
QUALIFY `load_plan_id` IS NULL
     OR ROW_NUMBER() OVER (PARTITION BY `load_plan_id` ORDER BY `last_modified_timestamp` DESC NULLS LAST, _ingested_at DESC) = 1;
